#include <iostream>
#include <string>

class Player {
private:
    std::string name;    // скрыто от внешнего кода
    int hp;

public:
    Player(std::string n, int h) : name(n), hp(h) {}   // конструктор

    void takeDamage(int dmg) {
        hp -= dmg;
        if (hp < 0) hp = 0;
    }

    int getHp() const { return hp; }      // const = метод не меняет объект
    std::string getName() const { return name; }
};

int main() {
    Player hero("Азиз", 100);
    hero.takeDamage(30);
    std::cout << hero.getName() << ": " << hero.getHp() << " HP" << std::endl;
    return 0;
}

