#include <iostream>

class Account {
private:
    int balance;

public:
    Account(int start) : balance(start) {}

    void deposit(int amount) {
        if (amount > 0) balance += amount;
    }

    void withdraw(int amount) {
        if (amount > 0 && amount <= balance) {   // защита от ухода в минус
            balance -= amount;
        }
    }

    int getBalance() const { return balance; }
};

int main() {
    Account acc(100);
    acc.deposit(50);
    acc.withdraw(200);
    std::cout << acc.getBalance() << std::endl;   // 150
    return 0;
}

