#include <iostream>
#include <vector>

int sumEven(const std::vector<int> &nums) {
    int total = 0;
    for (int n : nums) {          // range-based for: короче и безопаснее
        if (n % 2 == 0) total += n;
    }
    return total;
}

int main() {
    std::vector<int> data = {1, 2, 3, 4, 5, 6};
    std::cout << sumEven(data) << std::endl;   // 12
    return 0;
}

