#include <iostream>
#include <string>

class Unit {
protected:                          // protected = видно наследникам, но не снаружи
    std::string name;
public:
    Unit(std::string n) : name(n) {}
    void info() const { std::cout << "Юнит: " << name << std::endl; }
};

class Archer : public Unit {
public:
    Archer(std::string n) : Unit(n) {}      // вызываем конструктор родителя

    void shoot() const {
        std::cout << name << " стреляет!" << std::endl;
    }
};

int main() {
    Archer a("Леголас");
    a.info();      // метод родителя
    a.shoot();     // свой метод
    return 0;
}
